+\begin{definition}[Restriction and completion of combined polynomial outcomes]
+	\label{def:qld-pair-restriction-completion}
+	\lean{MIPStarRE.QPBT.recoverCombinedPair}
+	\lean{MIPStarRE.QPBT.combinedPolyEmbedding}
